from lxml import etree as ET
import re
from .field_value import FieldValue


class Packet(object):
    """
    Packet based on PDML output of tshark.

    A Packet offers methods to access parameters names and values.

    It is based on a slightly modified XML format, which is derived from the PDML,
    which can be displayed like this:

        from lxml import etree as ET
        print(ET.tostring(packet.xml, pretty_print=True))


    Methods:


    - **`findall`**: Find all values for parameter names that match a regular expression

    - **`keys`**: Return parameter names which are present in this packet

    - **`paths`**: Return parameter name paths which are present in this packet.

    - **`xpath`**: Return a list of parameter values, which match an XPath expression, that specifies parameter nodes.


    Attributes:

    - **`xml`**: packet in xml format

    - **`regex`**: optional regular expression to specify a subset of parameter names

    - **`path`**: XPath expression

    """

    def __init__(self, xml_packet, **kwargs):
        """
        Create a Packet from an XML string.

        :param str xml_packet:
            This XML string is a slightly converted PDML packet to simplify XPath expressions:
            "name" attributes are used as XML tags (or "_" if "name" is empty). Some irrelevant
            attributes are removed.
        """
        super(Packet, self).__init__(**kwargs)
        self._xml_packet = xml_packet

    def __str__(self):
        """
        Returns string representation of the packet

        :return: string representation of the packet
        :rtype: str
        """
        return ET.tostring(self._xml_packet, pretty_print=True).decode("utf-8").strip()

    @property
    def xml(self):
        """
        Return the XML representation of this packet.

        :return: XML representation of this packet
        :rtype: str
        """
        return self._xml_packet

    def findall(self, regex):
        """
        Find all values for parameter names that match a regular expression.

        :param str regex: regular expression, which specifies a set of parameter names
        :return: list of parameter values
        :rtype: list(:class:`FieldValue`)
        """
        keys = self.keys(regex)
        field_values = []
        for key in keys:
            field_values.extend(self.xpath(".//{name}".format(name=key)))
        return field_values

    def __getitem__(self, regex):
        """
        Return a parameter value for a parameter name, that matches a regular expression.

        Usage example:

        - packet["MME_UE_S1AP_ID"].show
        - packet["(?i)mme.*s1ap"].show

        :param str regex: regular expression, which should match only one parameter name
        :return: parameter value
        :rtype: :class:`FieldValue`
        :raises:
            KeyError, if no parameter name in the current packet matches regex
            LookupError, if more than one parameter name matches regex
        """
        result_list = self.findall(regex)
        length = len(result_list)
        if length == 0:
            raise KeyError(regex)
        elif length > 1:
            raise LookupError(regex)
        else:
            return result_list[0]

    def __contains__(self, regex):
        """
        Check whether there is any parameter name in this packet, that matches a regular expression.

        Usage example:

        - if "MME_UE_S1AP_ID" in packet:

        :param str regex: regular expression, which specifies parameter names, that will be checked for presence
        :return: True, if at least one parameter name in the current packet matches regex
        :rtype: bool
        """
        return bool(self.findall(regex))

    def keys(self, regex=None):
        """
        Return parameter names (optionally matching a regular expression), which are present in this packet.

        :param str regex: optional regular expression to specify a subset of parameter names
        :return: list of parameter names
        :rtype: list(str)
        """
        keys = sorted({element.tag for element in self._xml_packet.xpath(".//*")})
        if regex is None:
            return keys
        else:
            return [key for key in keys if re.search(regex, key)]

    def paths(self, regex=None):
        """
        Return parameter name paths (optionally matching a regular expression), which are present in this packet.

        Path example:

        - s1ap/s1ap.S1AP_PDU/s1ap.initiatingMessage_element/s1ap.value_element/s1ap.InitialContextSetupRequest_element/
        s1ap.protocolIEs/_[4]/s1ap.ProtocolIE_Field_element/s1ap.value_element/s1ap.E_RABToBeSetupListCtxtSUReq/_[1]/
        s1ap.ProtocolIE_SingleContainer_element/s1ap.value_element/s1ap.E_RABToBeSetupItemCtxtSUReq_element/
        s1ap.e_RABlevelQoSParameters_element/s1ap.qCI

        :param str regex: optional regular expression to specify a subset of parameter name paths
        :return: list of parameter name paths
        :rtype: list(str)
        """
        tree = ET.ElementTree(self._xml_packet)
        paths = [tree.getelementpath(element) for element in self._xml_packet.findall(".//*")]
        if regex is None:
            return paths
        else:
            return [path for path in paths if re.search(regex, path)]

    def xpath(self, path):
        """
        Return a list of parameter values, which match an XPath expression, that specifies parameter nodes.

        Usage example:

        - get QCI value for eRAB with ID 5: packet.xpath(".//s1ap.e_RAB_ID[@show='5']/..//s1ap.qCI")[0].showname

        :param str path: XPath expression

        :return: list of parameter values
        :rtype: list(:class:`FieldValue`)

        """
        values = self._xml_packet.xpath(path)
        return [
            FieldValue(
                show=value.get("show"),
                showname=value.get("showname"),
                value=value.get("value"))
            for value in values]
